  // SAVE STATE
  // ============================================
  // This effect runs whenever the state changes
  // It saves the current state to localStorage

  useEffect(() => {
    try {
      // Create an object with all the state we want to save
      const stateToSave = {
        currentStep,
        completedSteps: Array.from(completedSteps), // Convert Set to Array for storage
        currentUser,
        isLoggedIn,
        phoneNumber,
        activationDone,
