    } catch (e) {
      // If there's an error saving, log a warning
      console.warn('Could not save state:', e);
    }
  }, [
    // These are the dependencies - whenever any of these change, the effect runs
    currentStep, completedSteps, currentUser, isLoggedIn, phoneNumber, 
    activationDone, allMatches, incomingRequests, myMatches, chatContacts, 
    chatMessages, activeTab, myPhone, showMainMenu, searchCriteria, 
