    const completion = Math.round((filledFields.length / profileFields.length) * 100);

    // Update the stats object
    setStats({
      totalMatches: allMatches.length + myMatches.length,
      pendingRequests: incomingRequests.filter(r => r.status === 'pending').length,
      acceptedMatches: myMatches.length,
      unreadMessages: chatContacts.reduce((sum, c) => sum + (c.unread || 0), 0),
