    } catch (error) {
      console.error('Reject request error:', error);
      addNotification('❌ Error declining request.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  /**
   * Performs a search for matches based on criteria
   * 
   * This function:
   * 1. Builds search criteria from state
   * 2. Makes an API call to find matches
   * 3. Falls back to sample data if API fails
   */
  const performSearch = async () => {
    setIsSearching(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';
      const { gender, ageFrom, ageTo, county, town, religion, education } = searchCriteria;

      // Build age range string
      let ageRange = '';
      if (ageFrom && ageTo) {
        ageRange = `${ageFrom}-${ageTo}`;
      } else if (ageFrom) {
        ageRange = `${ageFrom}-100`;
      } else if (ageTo) {
        ageRange = `18-${ageTo}`;
      }

      // Try API first
      const result = await callApi('/match', 'POST', {
        phone: phone,
        gender: gender,
        ageRange: ageRange,
        town: town,
        county: county,
        religion: religion,
        education: education,
        offset: 0,
        limit: 10
      });

      if (result && result.status === 'success') {
        const matches = result.data?.matches || result.matches || [];
        const total = result.data?.total || result.total || 0;
        setTotalMatches(total);
        setAllMatches(matches);
        setHasMoreMatches(matches.length < total);
        if (matches.length > 0) {
          addNotification(`✅ Found ${matches.length} matches!`);
        } else {
          addNotification('🔍 No matches found. Try adjusting your criteria.', 'warning');
        }
      } else {
        // Fallback to sample data with filters
        let filtered = SAMPLE_MATCHES;

        // Apply filters
        if (gender && gender !== '') {
          // Filter by gender (mock - gender is not in sample data)
        }
        if (ageFrom || ageTo) {
          const from = parseInt(ageFrom) || 0;
          const to = parseInt(ageTo) || 100;
          filtered = filtered.filter(m => m.age >= from && m.age <= to);
        }
        if (town && town !== '') {
          filtered = filtered.filter(m => m.town.toLowerCase().includes(town.toLowerCase()));
        }
        if (county && county !== '') {
          filtered = filtered.filter(m => m.county && m.county.toLowerCase().includes(county.toLowerCase()));
        }
        if (religion && religion !== '') {
          filtered = filtered.filter(m => m.religion && m.religion.toLowerCase().includes(religion.toLowerCase()));
        }
        if (education && education !== '') {
          filtered = filtered.filter(m => m.education && m.education.toLowerCase().includes(education.toLowerCase()));
        }

        setAllMatches(filtered);
        setHasMoreMatches(true);
        if (filtered.length > 0) {
          addNotification(`✅ Found ${filtered.length} matches!`);
        } else {
          addNotification('🔍 No matches found. Try adjusting your criteria.', 'warning');
        }
      }
    } catch (error) {
      console.error('Search error:', error);
      addNotification('❌ Error searching matches.', 'error');
    } finally {
      setIsSearching(false);
    }
  };

  /**
