  /**
   * Starts a chat with a match
   * @param {Object} match - The match to chat with
   * 
   * This function:
   * 1. Checks if the contact exists in chatContacts
   * 2. If not, adds them
   * 3. Initializes chatMessages if needed
   * 4. Sets the selected contact and switches to chat tab
   */
  const startChat = (match) => {
    // Check if contact already exists
    if (!chatContacts.some(c => c.phone === match.phone)) {
      // Create new contact
      const newContact = {
        phone: match.phone,
        name: match.name,
        lastMessage: 'Start chatting...',
        lastMessageTime: 'Now',
        unread: 0,
        online: Math.random() > 0.5
      };
      setChatContacts(prev => [newContact, ...prev]);
    }

    // Initialize messages array if needed
    if (!chatMessages[match.phone]) {
      setChatMessages(prev => ({
        ...prev,
        [match.phone]: []
      }));
    }

    // Select the contact and switch to chat tab
    setSelectedChatContact(match);
    setActiveTab('chat');
    addNotification(`💬 Chat started with ${match.name}`);
  };

  // ============================================
