  /**
   * Activates the service with the activation keyword
   * 
   * This function:
   * 1. Makes an API call to activate the service
   * 2. If successful, shows the welcome message
   * 3. Sets activationDone to true
   */
  const activateService = async () => {
    setIsLoading(true);
    setResponseMessage('');
    setIsSuccess(false);
    setErrorDetails('');

    try {
      // Make API call with the activation keyword
      const result = await callApi('/activate', 'POST', { penzi: activationKeyword || 'PENZI' });

      if (result && result.status === 'success') {
        // Show the system response message
        setSystemResponseMessage(SYSTEM_MESSAGES.activation);
        setShowSystemResponse(true);

        setActivationDone(true);
        setResponseMessage('✅ Service activated successfully!');
        setIsSuccess(true);
        setCompletedSteps(prev => new Set([...prev, 0]));
        addNotification('✅ Service activated!');
        setMyPhone('0712345678');
        setActivationKeyword('');
      } else {
        setResponseMessage('❌ Invalid activation keyword. Please enter PENZI to continue.');
        setIsSuccess(false);
        setErrorDetails('Invalid activation keyword. Please enter PENZI to continue.');
        addNotification('❌ Invalid activation keyword', 'error');
      }
    } catch (error) {
      console.error('❌ Activation Error:', error);
      setResponseMessage('❌ Network error. Please check your connection.');
      setIsSuccess(false);
      setErrorDetails(error.message);
      addNotification('❌ Network error', 'error');
