  /**
   * Proceeds from activation to registration
   * Called when the user clicks the START button
   */
  const proceedToRegistration = () => {
    setCurrentStep(1);
    setShowSystemResponse(false);
    addNotification('📝 Proceeding to Registration...');
  };

  // ============================================
  // GO TO NEXT STEP (Registration)
  // ============================================

  /**
   * Handles navigation through registration steps
   * 
   * This function:
   * 1. Checks if the user exists (for step 2)
   * 2. Makes API calls for each step
   * 3. Shows appropriate system responses
   * 4. Navigates to the next step or dashboard
   */
  const goToNextStep = async () => {
    const step = currentStep + 1;

    // If user exists error, go to dashboard
    if (userExistsError) {
      setShowMainMenu(true);
      setIsLoggedIn(true);
      setUserExistsError(false);
      setRegistrationError('');
      return;
    }

    // ============================================
    // STEP 2: SERVICE REGISTRATION
    // ============================================
    if (step === 2) {
      setIsLoading(true);
      try {
        const data = {
          phone_number: formData.phone_number,
          name: formData.name,
          age: formData.age,
          gender: formData.gender,
          county: formData.county,
          town: formData.town
        };

        // Check if user already exists
        const result = await callApi('/register', 'POST', data);

        if (result && result.status === 'error' && result.message === 'User already exists') {
          setRegistrationError('⚠️ An account already exists with this phone number.');
          setUserExistsError(true);
          addNotification('⚠️ User already exists.', 'warning');

          const partialUser = {
            phone: formData.phone_number || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi',
            county: formData.county || 'Nairobi'
          };
          setCurrentUser(partialUser);
          setMyPhone(formData.phone_number || '0712345678');
          setIsLoading(false);
          return;
        }

        if (result && result.status === 'success') {
          // Show registration success message
          setSystemResponseMessage(SYSTEM_MESSAGES.registrationSuccess(formData.name || 'User'));
          setShowSystemResponse(true);

          setMyPhone(formData.phone_number || '0712345678');
          setCompletedSteps(prev => new Set([...prev, 1]));
          addNotification('✅ Registration complete!');

          // Create user object
          const newUser = {
            phone: formData.phone_number || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi',
            county: formData.county || 'Nairobi'
          };
          setCurrentUser(newUser);
          setCurrentStep(2);

          // Show success screen
          showSuccess('🎉 Congratulations!', 'Your account has been successfully created.\n\nYou may now complete your dating profile.');
          setIsLoading(false);
          return;
        } else {
          const errorMsg = result?.message || 'Registration failed. Please try again.';
          setRegistrationError(errorMsg);
          addNotification('❌ ' + errorMsg, 'error');
          setIsLoading(false);
          return;
        }
      } catch (error) {
        console.error('Registration error:', error);
        setRegistrationError('Network error. Please try again.');
        addNotification('❌ Network error', 'error');
        setIsLoading(false);
        return;
      }
    }

    // ============================================
    // STEP 3: DETAILS REGISTRATION
    // ============================================
    if (step === 3) {
      setIsLoading(true);
      try {
        const phone = currentUser?.phone || myPhone || '0712345678';
        const data = {
          education_level: formData.education_level,
          profession: formData.profession,
          marital_status: formData.marital_status,
          religion: formData.religion,
          ethnicity: formData.ethnicity
        };

        const result = await callApi(`/${phone}/complete-profile`, 'POST', data);

        if (result && result.status === 'success') {
          // Check if all details were provided
          const hasAllDetails = formData.education_level && formData.profession && 
                               formData.marital_status && formData.religion && formData.ethnicity;

          // Show appropriate message
          if (hasAllDetails) {
            setSystemResponseMessage(SYSTEM_MESSAGES.detailsSuccess);
          } else {
            setSystemResponseMessage(SYSTEM_MESSAGES.detailsNotProvided);
          }
          setShowSystemResponse(true);

          setCompletedSteps(prev => new Set([...prev, 2]));
          addNotification('✅ Profile completed!');

          // Update current user with new data
          if (currentUser) {
            setCurrentUser(prev => ({
              ...prev,
              education: formData.education_level,
              profession: formData.profession,
              marital_status: formData.marital_status,
              religion: formData.religion,
              ethnicity: formData.ethnicity
            }));
          }

          setCurrentStep(3);
          setIsLoading(false);
          return;
        } else {
          setRegistrationError(result?.message || 'Profile completion failed.');
          addNotification('❌ Profile completion failed.', 'error');
          setIsLoading(false);
          return;
        }
      } catch (error) {
        console.error('Details error:', error);
        setRegistrationError('Network error. Please try again.');
        addNotification('❌ Network error', 'error');
        setIsLoading(false);
        return;
      }
    }

    // ============================================
    // STEP 4: SELF-DESCRIPTION
    // ============================================
    if (step === 4) {
      setIsLoading(true);
      try {
        const phone = currentUser?.phone || myPhone || '0712345678';
        const result = await callApi(`/${phone}/self-description`, 'POST', { 
          description: formData.description 
        });

        if (result && result.status === 'success') {
          // Show success message
          setSystemResponseMessage(SYSTEM_MESSAGES.selfDescriptionSuccess);
          setShowSystemResponse(true);

          setCompletedSteps(prev => new Set([...prev, 3]));
          setRegistrationComplete(true);
          addNotification('✅ Registration complete!');

          // Update user with description
          if (currentUser) {
            setCurrentUser(prev => ({
              ...prev,
              description: formData.description
            }));
          }

          // Show success screen
          showSuccess('🎉 Registration Complete!', 'You are now registered for dating!\n\nTo search for a MPENZI, use the search feature and meet the person of your dreams.');

          // Auto-login and go to menu
          setIsLoggedIn(true);
          setIsFirstTimeUser(false);
          setIsLoading(false);
          return;
        } else {
          setRegistrationError(result?.message || 'Self-description failed.');
          addNotification('❌ Self-description failed.', 'error');
          setIsLoading(false);
          return;
        }
      } catch (error) {
        console.error('Self-description error:', error);
        setRegistrationError('Network error. Please try again.');
        addNotification('❌ Network error', 'error');
        setIsLoading(false);
        return;
      }
    }

    // For any other case, just go to next step
    if (step <= 4) {
      setCurrentStep(step);
    }
  };

