   */
  const renderRegistrationStep = () => {
    const step = currentStep + 1;
    const isLastStep = step === 4;
    const isStepCompleted = completedSteps.has(step - 1);
    const previewSms = buildSmsPreview(step);

    // Define the form fields for each step
    const getFields = () => {
      if (step === 2) {
        return [
          { key: 'phone_number', label: 'Full Name', placeholder: '0712345678', type: 'tel' },
          { key: 'name', label: 'Full Name', placeholder: 'Jamal Jalang\'o', type: 'text' },
          { key: 'age', label: 'Age', placeholder: '29', type: 'number' },
          { key: 'gender', label: 'Gender', type: 'select', options: ['Male', 'Female', 'Other'] },
          { key: 'county', label: 'County', placeholder: 'Mombasa', type: 'text' },
          { key: 'town', label: 'Town/City', placeholder: 'Bamburi', type: 'text' }
        ];
      }
      if (step === 3) {
        return [
          { key: 'education_level', label: 'Education Level', type: 'select', options: ['Primary', 'Secondary', 'Certificate', 'Diploma', 'Graduate', 'Post Graduate'] },
          { key: 'profession', label: 'Profession', placeholder: 'Accountant', type: 'text' },
          { key: 'marital_status', label: 'Marital Status', type: 'select', options: ['single', 'married', 'divorced', 'widowed', 'separated'] },
          { key: 'religion', label: 'Religion', placeholder: 'Muslim', type: 'text' },
          { key: 'ethnicity', label: 'Ethnicity', placeholder: 'Somali', type: 'text' }
        ];
      }
      if (step === 4) {
        return [
          { key: 'description', label: 'Describe yourself', placeholder: 'tall, dark and handsome', type: 'textarea' }
        ];
      }
      return [];
    };

    const fields = getFields();
    const stepTitles = {
      2: 'Create Your Dating Profile',
      3: 'Complete Your Dating Profile',
      4: 'Tell Us About Yourself'
    };
    const stepMessages = {
      2: 'Complete your registration details to start meeting compatible partners.',
      3: 'Tell us more about yourself so we can find compatible matches.',
      4: 'Tell us about yourself'
    };
    const stepIcons = {
      2: '📝',
      3: '📋',
      4: '💭'
    };

    const isFirstRegistrationStep = step === 2;

    return (
      <div className="registration-container">
        <div className="registration-card">
          <div className="registration-header">
            <span className="registration-icon">{stepIcons[step]}</span>
            <h1>{stepTitles[step]}</h1>
            <p className="subtitle">{stepMessages[step]}</p>
          </div>

          {activationDone && (
            <div className="progress-bar-container">
              <div className="progress-bar">
                <div className="progress-fill" style={{ width: `${getProgress()}%` }}></div>
              </div>
              <span className="progress-text">{getProgress()}% Complete • {completedSteps.size}/3</span>
            </div>
          )}

          {/* Show system response on the first registration step after activation */}
          {isFirstRegistrationStep && showSystemResponse && systemResponseMessage && (
            <div className="system-response-card">
              <div className="response-title">📨 System Response</div>
              <div className="response-body">{systemResponseMessage}</div>
            </div>
